from kitty.cli import main

if __name__ == "__main__":
    main()
"""Command-line interface: python3 -m kitty <command>."""

import argparse
import csv
import datetime
import json
import os
import sys
from typing import List, Optional

from kitty import ledger, reports, store
from kitty.money import KittyError, parse_currency


class _Parser(argparse.ArgumentParser):
    """Report usage errors like every other error: 'error: ...', exit 1."""

    def error(self, message):
        sys.stderr.write("error: {}\n".format(message))
        sys.exit(1)


def _build_parser() -> argparse.ArgumentParser:
    parser = _Parser(prog="kitty", description="Track shared expenses on group trips.")
    commands = parser.add_subparsers(dest="command", metavar="COMMAND", parser_class=_Parser)
    commands.required = True

    p = commands.add_parser("init", help="start a new kitty")
    p.add_argument("currency", metavar="CURRENCY")

    member = commands.add_parser("member", help="manage members")
    member_cmds = member.add_subparsers(dest="action", metavar="ACTION", parser_class=_Parser)
    member_cmds.required = True
    member_cmds.add_parser("add").add_argument("name", metavar="NAME")
    member_cmds.add_parser("remove").add_argument("name", metavar="NAME")
    member_cmds.add_parser("list")

    expense = commands.add_parser("expense", help="manage expenses")
    expense_cmds = expense.add_subparsers(dest="action", metavar="ACTION", parser_class=_Parser)
    expense_cmds.required = True
    p = expense_cmds.add_parser("add")
    p.add_argument("payer", metavar="PAYER")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("description", metavar="DESCRIPTION")
    split = p.add_mutually_exclusive_group()
    split.add_argument("--among", metavar="A,B")
    split.add_argument("--exact", metavar="A=30,B=20")
    split.add_argument("--shares", metavar="A=2,B=1")
    split.add_argument("--percent", metavar="A=60,B=40")
    p.add_argument("--currency")
    p.add_argument("--date")
    p.add_argument("--category", default="other")
    expense_cmds.add_parser("list")
    expense_cmds.add_parser("remove").add_argument("id", metavar="ID")

    payment = commands.add_parser("payment", help="record a repayment")
    payment_cmds = payment.add_subparsers(dest="action", metavar="ACTION", parser_class=_Parser)
    payment_cmds.required = True
    p = payment_cmds.add_parser("add")
    p.add_argument("frm", metavar="FROM")
    p.add_argument("to", metavar="TO")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("--currency")
    p.add_argument("--date")

    rate = commands.add_parser("rate", help="set exchange rates")
    rate_cmds = rate.add_subparsers(dest="action", metavar="ACTION", parser_class=_Parser)
    rate_cmds.required = True
    p = rate_cmds.add_parser("set")
    p.add_argument("currency", metavar="CURRENCY")
    p.add_argument("rate", metavar="RATE")

    commands.add_parser("balances", help="how far up or down each person is")
    commands.add_parser("settle", help="suggest payments to square up")
    commands.add_parser("history", help="entries affecting one person").add_argument(
        "name", metavar="NAME")
    commands.add_parser("report", help="spending per category per person")
    commands.add_parser("export", help="write expenses to CSV").add_argument("file", metavar="FILE")
    return parser


def _print_json(value) -> None:
    print(json.dumps(value, ensure_ascii=False))


def _today() -> str:
    return datetime.date.today().isoformat()


def _export(kitty: dict, path: str) -> None:
    if os.path.realpath(path) == os.path.realpath(store.FILENAME):
        raise KittyError("refusing to overwrite {} with the CSV export".format(store.FILENAME))
    try:
        with open(path, "w", newline="", encoding="utf-8") as f:
            csv.writer(f).writerows(reports.csv_rows(kitty))
    except OSError as e:
        raise KittyError("cannot write {}: {}".format(path, e.strerror or e))


def _run(args: argparse.Namespace) -> None:
    if args.command == "init":
        store.create(parse_currency(args.currency))
        return

    kitty = store.load()
    command = (args.command, getattr(args, "action", None))

    if command == ("member", "list"):
        _print_json(reports.member_list(kitty))
    elif command == ("expense", "list"):
        _print_json(reports.expense_list(kitty))
    elif args.command == "balances":
        _print_json(reports.balances(kitty))
    elif args.command == "settle":
        _print_json(reports.settle(kitty))
    elif args.command == "history":
        _print_json(reports.history(kitty, args.name))
    elif args.command == "report":
        _print_json(reports.report(kitty))
    elif args.command == "export":
        _export(kitty, args.file)
    else:
        if command == ("member", "add"):
            ledger.add_member(kitty, args.name)
        elif command == ("member", "remove"):
            ledger.remove_member(kitty, args.name)
        elif command == ("expense", "add"):
            expense_id = ledger.add_expense(
                kitty, args.payer, args.amount, args.description, args.date or _today(),
                among=args.among, exact=args.exact, shares=args.shares, percent=args.percent,
                currency=args.currency, category=args.category)
        elif command == ("expense", "remove"):
            ledger.remove_expense(kitty, args.id)
        elif command == ("payment", "add"):
            ledger.add_payment(kitty, args.frm, args.to, args.amount, args.date or _today(),
                               currency=args.currency)
        elif command == ("rate", "set"):
            ledger.set_rate(kitty, args.currency, args.rate)
        store.save(kitty)
        if command == ("expense", "add"):
            print(expense_id)


def main(argv: Optional[List[str]] = None) -> None:
    args = _build_parser().parse_args(argv)
    try:
        _run(args)
    except KittyError as e:
        sys.stderr.write("error: {}\n".format(e))
        sys.exit(1)
    sys.exit(0)
"""Changes to a kitty: members, rates, expenses and payments.

Every function validates fully before touching the kitty, so a failed
command leaves it unchanged. The caller saves.
"""

import re
from decimal import Decimal
from typing import List, Optional, Tuple

from kitty.money import (
    KittyError,
    allocate,
    convert,
    parse_amount,
    parse_currency,
    parse_date,
    parse_rate,
)
from kitty.store import clean_new_name, resolve_member

_SHARES_RE = re.compile(r"^\d+\Z", re.ASCII)


def add_member(kitty: dict, name: str) -> None:
    kitty["members"].append(clean_new_name(kitty, name))


def remove_member(kitty: dict, name: str) -> None:
    member = resolve_member(kitty, name)
    used = any(
        e["payer"] == member or any(n == member for n, _ in e["shares"])
        for e in kitty["expenses"]
    ) or any(p["from"] == member or p["to"] == member for p in kitty["payments"])
    if used:
        raise KittyError("cannot remove {}: they appear in expenses or payments".format(member))
    kitty["members"].remove(member)


def set_rate(kitty: dict, currency: str, rate_text: str) -> None:
    currency = parse_currency(currency)
    if currency == kitty["base_currency"]:
        raise KittyError("{} is the base currency".format(currency))
    parse_rate(rate_text)
    kitty["rates"][currency] = rate_text


def _rate_for(kitty: dict, currency: Optional[str]) -> Tuple[str, str, Decimal]:
    """Return (currency, rate text, rate) for an entry being added now."""
    if currency is None:
        return kitty["base_currency"], "1", Decimal(1)
    currency = parse_currency(currency)
    if currency == kitty["base_currency"]:
        return currency, "1", Decimal(1)
    if currency not in kitty["rates"]:
        raise KittyError("no rate set for {}; use: rate set {} RATE".format(currency, currency))
    text = kitty["rates"][currency]
    return currency, text, Decimal(text)


def _parse_names(kitty: dict, text: str) -> List[str]:
    names = []
    for part in text.split(","):
        if "=" in part:
            raise KittyError("--among takes names only: {!r}".format(part))
        names.append(resolve_member(kitty, part))
    return _check_unique(names)


def _parse_pairs(kitty: dict, text: str, option: str) -> List[Tuple[str, str]]:
    pairs = []
    for part in text.split(","):
        if "=" not in part:
            raise KittyError("{} wants NAME=VALUE, got {!r}".format(option, part))
        name, value = part.split("=", 1)
        pairs.append((resolve_member(kitty, name), value.strip()))
    _check_unique([n for n, _ in pairs])
    return pairs


def _check_unique(names: List[str]) -> List[str]:
    seen = set()
    for name in names:
        if name in seen:
            raise KittyError("{} is listed twice".format(name))
        seen.add(name)
    return names


def _split(kitty: dict, amount_cents: int, among: Optional[str], exact: Optional[str],
           shares: Optional[str], percent: Optional[str]) -> Tuple[List[str], List[int]]:
    """Return participant names (in split order) and their integer weights."""
    given = [o for o in (among, exact, shares, percent) if o is not None]
    if len(given) > 1:
        raise KittyError("use only one of --among, --exact, --shares, --percent")
    if among is not None:
        names = _parse_names(kitty, among)
        return names, [1] * len(names)
    if exact is not None:
        pairs = _parse_pairs(kitty, exact, "--exact")
        weights = [parse_amount(v) for _, v in pairs]
        if sum(weights) != amount_cents:
            raise KittyError("--exact amounts must add up to the expense amount")
        return [n for n, _ in pairs], weights
    if shares is not None:
        pairs = _parse_pairs(kitty, shares, "--shares")
        weights = []
        for name, value in pairs:
            if not _SHARES_RE.match(value) or int(value) == 0:
                raise KittyError("shares must be positive whole numbers: {}={}".format(name, value))
            weights.append(int(value))
        return [n for n, _ in pairs], weights
    if percent is not None:
        pairs = _parse_pairs(kitty, percent, "--percent")
        weights = [parse_amount(v) for _, v in pairs]  # hundredths of a percent
        if sum(weights) != 10000:
            raise KittyError("--percent must add up to 100")
        return [n for n, _ in pairs], weights
    if not kitty["members"]:
        raise KittyError("the kitty has no members yet")
    return list(kitty["members"]), [1] * len(kitty["members"])


def _next_seq(kitty: dict) -> int:
    seq = kitty["next_seq"]
    kitty["next_seq"] = seq + 1
    return seq


def add_expense(kitty: dict, payer: str, amount_text: str, description: str, date: str, *,
                among: Optional[str] = None, exact: Optional[str] = None,
                shares: Optional[str] = None, percent: Optional[str] = None,
                currency: Optional[str] = None, category: str = "other") -> int:
    payer = resolve_member(kitty, payer)
    amount_cents = parse_amount(amount_text)
    date = parse_date(date)
    currency, rate_text, rate = _rate_for(kitty, currency)
    names, weights = _split(kitty, amount_cents, among, exact, shares, percent)
    base_cents = convert(amount_cents, rate)
    expense_id = kitty["next_id"]
    kitty["next_id"] = expense_id + 1
    kitty["expenses"].append({
        "id": expense_id,
        "seq": _next_seq(kitty),
        "date": date,
        "payer": payer,
        "description": description,
        "amount_cents": amount_cents,
        "currency": currency,
        "rate": rate_text,
        "base_cents": base_cents,
        "category": category,
        "shares": [[n, c] for n, c in zip(names, allocate(base_cents, weights))],
    })
    return expense_id


def remove_expense(kitty: dict, id_text: str) -> None:
    if not _SHARES_RE.match(id_text.strip()):
        raise KittyError("bad expense id: {!r}".format(id_text))
    expense_id = int(id_text)
    for i, expense in enumerate(kitty["expenses"]):
        if expense["id"] == expense_id:
            del kitty["expenses"][i]
            return
    raise KittyError("no expense with id {}".format(expense_id))


def add_payment(kitty: dict, frm: str, to: str, amount_text: str, date: str,
                currency: Optional[str] = None) -> None:
    frm = resolve_member(kitty, frm)
    to = resolve_member(kitty, to)
    if frm == to:
        raise KittyError("{} cannot pay themselves".format(frm))
    amount_cents = parse_amount(amount_text)
    date = parse_date(date)
    currency, rate_text, rate = _rate_for(kitty, currency)
    kitty["payments"].append({
        "seq": _next_seq(kitty),
        "date": date,
        "from": frm,
        "to": to,
        "amount_cents": amount_cents,
        "currency": currency,
        "rate": rate_text,
        "base_cents": convert(amount_cents, rate),
    })
"""Money parsing, formatting, conversion and cent allocation.

All money is integer cents; rates are Decimals. No floats anywhere.
"""

import datetime
import re
from decimal import ROUND_HALF_UP, Decimal
from typing import List

_AMOUNT_RE = re.compile(r"^\d+(\.\d{1,2})?\Z", re.ASCII)
_DECIMAL_RE = re.compile(r"^\d+(\.\d+)?\Z", re.ASCII)
_CURRENCY_RE = re.compile(r"^[A-Za-z]{3}\Z", re.ASCII)
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}\Z", re.ASCII)


class KittyError(Exception):
    """A user-facing error: reported as 'error: ...' with exit status 1."""


def parse_amount(text: str) -> int:
    """Parse a positive amount with at most two decimals into cents."""
    if not _AMOUNT_RE.match(text):
        raise KittyError("bad amount: {!r}".format(text))
    cents = int(Decimal(text) * 100)
    if cents <= 0:
        raise KittyError("amount must be positive: {!r}".format(text))
    return cents


def parse_rate(text: str) -> Decimal:
    """Parse a positive exchange rate of any precision."""
    if not _DECIMAL_RE.match(text):
        raise KittyError("bad rate: {!r}".format(text))
    rate = Decimal(text)
    if rate <= 0:
        raise KittyError("rate must be positive: {!r}".format(text))
    return rate


def parse_currency(text: str) -> str:
    """Parse a three-letter currency code, returned uppercase."""
    if not _CURRENCY_RE.match(text):
        raise KittyError("bad currency code: {!r}".format(text))
    return text.upper()


def parse_date(text: str) -> str:
    """Validate a YYYY-MM-DD date and return it unchanged."""
    if _DATE_RE.match(text):
        try:
            datetime.date.fromisoformat(text)
            return text
        except ValueError:
            pass
    raise KittyError("bad date (want YYYY-MM-DD): {!r}".format(text))


def format_cents(cents: int) -> str:
    """Format cents as a string with exactly two decimals."""
    sign = "-" if cents < 0 else ""
    whole, frac = divmod(abs(cents), 100)
    return "{}{}.{:02d}".format(sign, whole, frac)


def convert(cents: int, rate: Decimal) -> int:
    """Convert cents at a rate, rounding half up to a whole cent."""
    return int((Decimal(cents) * rate).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def allocate(total: int, weights: List[int]) -> List[int]:
    """Split total cents by weights: round each down, then hand out the
    leftover cents one each in order."""
    weight_sum = sum(weights)
    shares = [total * w // weight_sum for w in weights]
    for i in range(total - sum(shares)):
        shares[i] += 1
    return shares
"""Read-only views of a kitty, as JSON-ready values (money as strings)."""

from typing import Dict, List

from kitty.money import format_cents
from kitty.store import resolve_member


def member_list(kitty: dict) -> List[str]:
    return list(kitty["members"])


def expense_list(kitty: dict) -> List[dict]:
    return [
        {
            "id": e["id"],
            "date": e["date"],
            "payer": e["payer"],
            "description": e["description"],
            "amount": format_cents(e["amount_cents"]),
            "currency": e["currency"],
            "base_amount": format_cents(e["base_cents"]),
            "category": e["category"],
            "shares": {name: format_cents(cents) for name, cents in e["shares"]},
        }
        for e in sorted(kitty["expenses"], key=lambda e: e["id"])
    ]


def balance_cents(kitty: dict) -> Dict[str, int]:
    """Positive: owed money. Negative: owes money."""
    bal = {name: 0 for name in kitty["members"]}
    for e in kitty["expenses"]:
        bal[e["payer"]] += e["base_cents"]
        for name, cents in e["shares"]:
            bal[name] -= cents
    for p in kitty["payments"]:
        bal[p["from"]] += p["base_cents"]
        bal[p["to"]] -= p["base_cents"]
    return bal


def balances(kitty: dict) -> Dict[str, str]:
    return {name: format_cents(cents) for name, cents in balance_cents(kitty).items()}


def settle(kitty: dict) -> List[dict]:
    """Repeatedly have the biggest debtor pay the biggest creditor enough to
    square one of them. Ties go alphabetically, ignoring case."""
    bal = balance_cents(kitty)
    payments = []
    while any(bal.values()):
        debtor = min((n for n in bal if bal[n] < 0), key=lambda n: (bal[n], n.casefold()))
        creditor = min((n for n in bal if bal[n] > 0), key=lambda n: (-bal[n], n.casefold()))
        amount = min(-bal[debtor], bal[creditor])
        payments.append({"from": debtor, "to": creditor, "amount": format_cents(amount)})
        bal[debtor] += amount
        bal[creditor] -= amount
    return payments


def history(kitty: dict, name: str) -> List[dict]:
    member = resolve_member(kitty, name)
    entries = []
    for e in kitty["expenses"]:
        shares = dict(e["shares"])
        if e["payer"] == member or member in shares:
            change = (e["base_cents"] if e["payer"] == member else 0) - shares.get(member, 0)
            entries.append((e["date"], e["seq"], e["description"], change))
    for p in kitty["payments"]:
        if p["from"] == member:
            entries.append((p["date"], p["seq"], "Payment to " + p["to"], p["base_cents"]))
        elif p["to"] == member:
            entries.append((p["date"], p["seq"], "Payment from " + p["from"], -p["base_cents"]))
    result = []
    running = 0
    for date, _, description, change in sorted(entries):
        running += change
        result.append({"date": date, "description": description,
                       "change": format_cents(change), "balance": format_cents(running)})
    return result


def report(kitty: dict) -> Dict[str, Dict[str, str]]:
    """Each person's share of spending per category (payments ignored)."""
    totals = {}  # type: Dict[str, Dict[str, int]]
    for e in kitty["expenses"]:
        category = totals.setdefault(e["category"], {})
        for name, cents in e["shares"]:
            category[name] = category.get(name, 0) + cents
    return {
        category: {n: format_cents(totals[category][n])
                   for n in kitty["members"] if n in totals[category]}
        for category in sorted(totals)
    }


CSV_HEADER = ["id", "date", "payer", "description", "amount", "currency", "category", "base_amount"]


def csv_rows(kitty: dict) -> List[List[str]]:
    rows = [list(CSV_HEADER)]
    for e in expense_list(kitty):
        rows.append([str(e["id"]), e["date"], e["payer"], e["description"], e["amount"],
                     e["currency"], e["category"], e["base_amount"]])
    return rows
"""The kitty.json file and member-name resolution."""

import json
import os
import tempfile

from kitty.money import KittyError, parse_rate

FILENAME = "kitty.json"

_INT = "int"  # an int that is not a bool

_KEYS = {
    "version": _INT,
    "base_currency": str,
    "members": list,
    "rates": dict,
    "next_id": _INT,
    "next_seq": _INT,
    "expenses": list,
    "payments": list,
}

_EXPENSE_KEYS = {
    "id": _INT, "seq": _INT, "date": str, "payer": str, "description": str,
    "amount_cents": _INT, "currency": str, "rate": str, "base_cents": _INT,
    "category": str, "shares": list,
}

_PAYMENT_KEYS = {
    "seq": _INT, "date": str, "from": str, "to": str, "amount_cents": _INT,
    "currency": str, "rate": str, "base_cents": _INT,
}


def _is(value, kind) -> bool:
    if kind is _INT:
        return isinstance(value, int) and not isinstance(value, bool)
    return isinstance(value, kind)


def _has_keys(record, keys: dict) -> bool:
    return isinstance(record, dict) and all(_is(record.get(k), kind) for k, kind in keys.items())


def _is_valid(kitty) -> bool:
    """Check everything the rest of kitty relies on when reading the file."""
    if not _has_keys(kitty, _KEYS) or kitty["version"] != 1:
        return False
    members = kitty["members"]
    if not all(isinstance(m, str) for m in members):
        return False
    if len({m.casefold() for m in members}) != len(members):
        return False
    try:
        for rate in kitty["rates"].values():
            parse_rate(rate)
    except (KittyError, TypeError):
        return False
    known = set(members)
    for e in kitty["expenses"]:
        if not _has_keys(e, _EXPENSE_KEYS) or e["payer"] not in known:
            return False
        shares = e["shares"]
        if not all(isinstance(s, list) and len(s) == 2 and s[0] in known and _is(s[1], _INT)
                   for s in shares):
            return False
        if sum(s[1] for s in shares) != e["base_cents"]:
            return False
    for p in kitty["payments"]:
        if not _has_keys(p, _PAYMENT_KEYS) or p["from"] not in known or p["to"] not in known:
            return False
    return True


def new_kitty(base_currency: str) -> dict:
    return {
        "version": 1,
        "base_currency": base_currency,
        "members": [],
        "rates": {},
        "next_id": 1,
        "next_seq": 1,
        "expenses": [],
        "payments": [],
    }


def create(base_currency: str, path: str = FILENAME) -> None:
    if os.path.exists(path):
        raise KittyError("{} already exists".format(path))
    save(new_kitty(base_currency), path)


def load(path: str = FILENAME) -> dict:
    if not os.path.exists(path):
        raise KittyError("no {} here; run init first".format(path))
    try:
        with open(path, encoding="utf-8") as f:
            kitty = json.load(f)
    except (OSError, UnicodeDecodeError, ValueError) as e:
        raise KittyError("cannot read {}: {}".format(path, e))
    if not _is_valid(kitty):
        raise KittyError("{} is not a valid kitty file".format(path))
    return kitty


def _file_mode(path: str) -> int:
    """The existing file's permissions, or the umask default for a new file."""
    try:
        return os.stat(path).st_mode & 0o777
    except FileNotFoundError:
        umask = os.umask(0)
        os.umask(umask)
        return 0o666 & ~umask


def save(kitty: dict, path: str = FILENAME) -> None:
    """Write atomically: a temp file in the same directory, then rename.
    The file keeps its permissions (temp files are created owner-only)."""
    directory = os.path.dirname(os.path.abspath(path))
    try:
        mode = _file_mode(path)
        with tempfile.NamedTemporaryFile(
            "w", encoding="utf-8", dir=directory, prefix=".kitty-", suffix=".tmp", delete=False
        ) as f:
            json.dump(kitty, f, ensure_ascii=False, indent=2)
            f.write("\n")
        os.chmod(f.name, mode)
        os.replace(f.name, path)
    except OSError as e:
        raise KittyError("cannot write {}: {}".format(path, e))


def resolve_member(kitty: dict, name: str) -> str:
    """Find a member ignoring case; return the name as first added."""
    wanted = name.strip().casefold()
    for member in kitty["members"]:
        if member.casefold() == wanted:
            return member
    raise KittyError("unknown member: {}".format(name))


def clean_new_name(kitty: dict, name: str) -> str:
    name = name.strip()
    if not name:
        raise KittyError("member name cannot be empty")
    if "," in name or "=" in name:
        raise KittyError("member name cannot contain ',' or '=': {}".format(name))
    for member in kitty["members"]:
        if member.casefold() == name.casefold():
